<?php declare(strict_types=1); namespace App\People\Domain\ValueObject; final readonly class PersonName { private function __construct(private string $firstName,private string $lastName){} public static function fromStrings(string $first,string $last):self{$first=trim($first);$last=trim($last);if($first===''||$last==='')throw new \InvalidArgumentException('First and last name are required.');return new self($first,$last);} public function firstName():string{return $this->firstName;} public function lastName():string{return $this->lastName;} public function fullName():string{return $this->firstName.' '.$this->lastName;} }
